import{_ as e,o as a,c as n,ah as r}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"Acceptance checklist","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/recette.md","filePath":"src/en/guide/recette.md"}'),d={name:"en/guide/recette.md"};function o(s,t,h,i,l,c){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="acceptance-checklist" tabindex="-1">Acceptance checklist <a class="header-anchor" href="#acceptance-checklist" aria-label="Permalink to &quot;Acceptance checklist&quot;">​</a></h1><p>This page is for checking ERA <strong>by hand</strong>, role by role, after every update (Alpha or SaaS), before announcing it to users. It doesn&#39;t replace the automated tests: on every change, they already check that each role only opens its own pages, and that the money and grades journeys give the right amounts and averages.</p><p>The checklist focuses on what a machine can&#39;t see: a PDF that is readable and well laid out, an e-mail or SMS actually received, a file sent from a phone, a real payment, a printout.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>Have <strong>one test account per role</strong>, on the school concerned, with an e-mail address you can read.</li><li>Run at least part of the checklist <strong>on a phone</strong>, especially the parent, student, teacher and school life roles.</li><li>Create data under your own name (&quot;Acceptance test&quot;) and delete or cancel it at the end, so the school&#39;s figures aren&#39;t skewed.</li><li>Never test a real online payment with a large sum: the smallest accepted amount is enough.</li></ul><div class="info custom-block"><p class="custom-block-title">Reporting a problem</p><p>For each item that doesn&#39;t give the expected result, note its <strong>number</strong> (for instance PAR-4), the account used, what you saw and a screenshot. An item you didn&#39;t test is noted &quot;not done&quot;, not &quot;OK&quot;.</p></div><h2 id="all-roles" tabindex="-1">All roles <a class="header-anchor" href="#all-roles" aria-label="Permalink to &quot;All roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>To do</th><th>Expected</th></tr></thead><tbody><tr><td>TR-1</td><td>Sign in with each test account.</td><td>The role&#39;s dashboard opens; the menu only shows its own sections.</td></tr><tr><td>TR-2</td><td>If two-factor authentication is on, sign in from a new browser.</td><td>A 6-digit code arrives by e-mail within a minute and opens the session.</td></tr><tr><td>TR-3</td><td>Tick &quot;Remember this device&quot;, sign out, sign back in.</td><td>No code is asked for again on this browser.</td></tr><tr><td>TR-4</td><td>Use &quot;Forgot your password?&quot;.</td><td>The e-mail arrives; the link works only once.</td></tr><tr><td>TR-5</td><td>Open the notification bell.</td><td>Recent notifications show; their links lead to the right page.</td></tr><tr><td>TR-6</td><td>Switch the language to French, then back to English.</td><td>No text stays in the other language or shows a raw code.</td></tr><tr><td>TR-7</td><td>Open a page&#39;s help, then start a guided tour.</td><td>The help matches the page; the tour runs to the end.</td></tr><tr><td>TR-8</td><td>Staff member: submit a request from <strong>My leave requests</strong>.</td><td>The request shows <strong>Pending</strong> and appears in management&#39;s <strong>To approve</strong>.</td></tr></tbody></table><h2 id="administration" tabindex="-1">Administration <a class="header-anchor" href="#administration" aria-label="Permalink to &quot;Administration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>To do</th><th>Expected</th></tr></thead><tbody><tr><td>ADM-1</td><td><strong>New user</strong> with your own address, then <strong>Create the user</strong>.</td><td>The invitation arrives by e-mail; its link lets you choose a password.</td></tr><tr><td>ADM-2</td><td><strong>Resend invitation</strong> to an account not activated yet.</td><td>A new e-mail arrives; its link activates the account.</td></tr><tr><td>ADM-3</td><td><strong>Change the logo</strong> in the settings.</td><td>The new logo shows in the menu and on the public home page.</td></tr><tr><td>ADM-4</td><td><strong>Publish / republish bulletins</strong> for a class.</td><td>Parents get a single notification; the report card opens on their side.</td></tr><tr><td>ADM-5</td><td>Open a report card PDF.</td><td>Header, grades, averages, ranks and comments are readable, with no cut-off text; the printout fits the page.</td></tr><tr><td>ADM-6</td><td><strong>Back up now</strong>, then download the archive.</td><td>The archive downloads and opens.</td></tr><tr><td>ADM-7</td><td>Export a class&#39;s grades to Excel, then import the file back.</td><td>The file opens in Excel; the import creates no duplicate and no error.</td></tr><tr><td>ADM-8</td><td>Open the school&#39;s public home page on a phone.</td><td>Texts, images and contacts display properly, with nothing overflowing.</td></tr></tbody></table><h2 id="teacher" tabindex="-1">Teacher <a class="header-anchor" href="#teacher" aria-label="Permalink to &quot;Teacher&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>To do</th><th>Expected</th></tr></thead><tbody><tr><td>ENS-1</td><td>On a phone, <strong>Take attendance</strong> for a class, then <strong>Save roll call</strong>.</td><td>The list is easy to use with a finger; the roll call shows for school life.</td></tr><tr><td>ENS-2</td><td><strong>New evaluation</strong>, then enter the <strong>Grades</strong> of a few students.</td><td>The scale is prefilled with 20; decimal grades are accepted.</td></tr><tr><td>ENS-3</td><td>From <strong>My homeroom class</strong>, enter end-of-period comments.</td><td>They appear on the report card PDF, without being cut off.</td></tr><tr><td>ENS-4</td><td><strong>Lesson log</strong> → <strong>New entry</strong> with an attached document.</td><td>The entry appears in the student&#39;s <strong>Lesson log</strong>; the attachment opens.</td></tr><tr><td>ENS-5</td><td>Look at your timetable.</td><td>The slots match the ones entered by the administration.</td></tr></tbody></table><h2 id="school-life" tabindex="-1">School life <a class="header-anchor" href="#school-life" aria-label="Permalink to &quot;School life&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>To do</th><th>Expected</th></tr></thead><tbody><tr><td>VS-1</td><td>Open <strong>Absence justifications</strong> and look at a supporting document.</td><td>The document (photo or PDF) opens and is readable.</td></tr><tr><td>VS-2</td><td><strong>Approve</strong> one justification, <strong>Reject</strong> another.</td><td>The parent is told of each decision.</td></tr><tr><td>VS-3</td><td><strong>New incident</strong>, then <strong>Convene council</strong>.</td><td>The council shows with its date and members.</td></tr><tr><td>VS-4</td><td><strong>Record decision</strong>, then <strong>Download minutes</strong>.</td><td>The PDF includes the decision and those present, readable and well laid out.</td></tr><tr><td>VS-5</td><td>On a phone, <strong>Cafeteria attendance</strong> with <strong>Everyone ate</strong>.</td><td>The roll call is saved in one gesture.</td></tr><tr><td>VS-6</td><td>On a phone, <strong>Transport attendance</strong> for <strong>Pickup</strong>, then <strong>Drop-off</strong>.</td><td>Both roll calls are saved.</td></tr></tbody></table><h2 id="secretariat" tabindex="-1">Secretariat <a class="header-anchor" href="#secretariat" aria-label="Permalink to &quot;Secretariat&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>To do</th><th>Expected</th></tr></thead><tbody><tr><td>SEC-1</td><td>Submit an application from the public page, with attached documents.</td><td>It arrives in <strong>Applications to review</strong>; the documents open.</td></tr><tr><td>SEC-2</td><td><strong>Review</strong>, then <strong>Approve</strong> the application and <strong>Assign to a class</strong>.</td><td>The family is told by e-mail; the student appears in the class.</td></tr><tr><td>SEC-3</td><td><strong>Reject</strong> another application with a reason.</td><td>The family receives the rejection with the reason.</td></tr><tr><td>SEC-4</td><td>Review the site transfer request from PAR-3, then approve it.</td><td>Once the transfer is validated, the student appears on the destination site.</td></tr><tr><td>SEC-5</td><td>Move a student to another class.</td><td>Their fees follow; their past grades stay visible.</td></tr></tbody></table><h2 id="cashier" tabindex="-1">Cashier <a class="header-anchor" href="#cashier" aria-label="Permalink to &quot;Cashier&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>To do</th><th>Expected</th></tr></thead><tbody><tr><td>CAI-1</td><td>Record a cash payment, then <strong>Download receipt</strong>.</td><td>The receipt PDF shows the right student and amount, and prints properly.</td></tr><tr><td>CAI-2</td><td>Record a bank transfer payment with a reference.</td><td>The reference shows on the receipt.</td></tr><tr><td>CAI-3</td><td>Enter an expense with a supporting document.</td><td>The document opens; the expense goes for approval.</td></tr><tr><td>CAI-4</td><td>Run the accounting export for one month.</td><td>The file opens in the spreadsheet and its totals match the screen.</td></tr><tr><td>CAI-5</td><td>If online payment is on, check the payment made in PAR-5.</td><td>It shows as paid, with the right reference.</td></tr></tbody></table><h2 id="parent" tabindex="-1">Parent <a class="header-anchor" href="#parent" aria-label="Permalink to &quot;Parent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>To do</th><th>Expected</th></tr></thead><tbody><tr><td>PAR-1</td><td>On a phone, open the report card published in ADM-4.</td><td>The PDF opens and is readable on the phone.</td></tr><tr><td>PAR-2</td><td><strong>Justify</strong> an absence with a <strong>Supporting document</strong> taken as a photo.</td><td>The photo uploads from the phone; school life sees it.</td></tr><tr><td>PAR-3</td><td><strong>Request a transfer</strong> to another site for your child.</td><td>The request reaches the secretariat (see SEC-4).</td></tr><tr><td>PAR-4</td><td>Pick optional services, then <strong>Save my choices</strong>.</td><td>The matching fees show in the balance.</td></tr><tr><td>PAR-5</td><td><strong>Pay online</strong> the smallest possible amount, then <strong>Send payment request</strong>.</td><td>The request reaches the phone; the payment goes through once confirmed; the balance drops.</td></tr><tr><td>PAR-6</td><td>Repeat PAR-5, declining the confirmation on the phone.</td><td>The payment isn&#39;t counted; the balance doesn&#39;t change.</td></tr><tr><td>PAR-7</td><td><strong>Download receipt</strong> for a payment.</td><td>The receipt PDF is the same as the cashier&#39;s.</td></tr></tbody></table><h2 id="student" tabindex="-1">Student <a class="header-anchor" href="#student" aria-label="Permalink to &quot;Student&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>To do</th><th>Expected</th></tr></thead><tbody><tr><td>ELV-1</td><td>On a phone, open <strong>My portal</strong>.</td><td>The Grades, Report cards, Documents and Lesson log sections show.</td></tr><tr><td>ELV-2</td><td>Open the report card, then the attachment of ENS-4.</td><td>Both files open.</td></tr><tr><td>ELV-3</td><td>Check a grade entered in ENS-2.</td><td>The grade and the evaluation are the ones the teacher entered.</td></tr></tbody></table><h2 id="boarding" tabindex="-1">Boarding <a class="header-anchor" href="#boarding" aria-label="Permalink to &quot;Boarding&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>To do</th><th>Expected</th></tr></thead><tbody><tr><td>INT-1</td><td><strong>New bed</strong>, then assign a student to it.</td><td>The bed shows as occupied.</td></tr><tr><td>INT-2</td><td>On a phone, <strong>Boarding attendance</strong> for Evening, then Morning.</td><td>Both roll calls are saved; an absent student is flagged.</td></tr></tbody></table><h2 id="infirmary" tabindex="-1">Infirmary <a class="header-anchor" href="#infirmary" aria-label="Permalink to &quot;Infirmary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>To do</th><th>Expected</th></tr></thead><tbody><tr><td>INF-1</td><td><strong>New visit</strong> with the outcome <strong>Returned to class</strong>.</td><td>The visit shows in the list; no parent is notified.</td></tr><tr><td>INF-2</td><td><strong>New visit</strong> with the outcome <strong>Sent home</strong>.</td><td>The parents get a notification with the reason and the time.</td></tr></tbody></table><h2 id="document-management" tabindex="-1">Document management <a class="header-anchor" href="#document-management" aria-label="Permalink to &quot;Document management&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>To do</th><th>Expected</th></tr></thead><tbody><tr><td>GED-1</td><td>In a student&#39;s file, <strong>File</strong> a PDF.</td><td>The document appears under the right type and opens.</td></tr><tr><td>GED-2</td><td>On a phone, <strong>Take a photo</strong> of two printed pages.</td><td>The pages are joined into a single readable PDF, in order.</td></tr><tr><td>GED-3</td><td><strong>Search the documents</strong> for a word from the pages of GED-2.</td><td>The document is found.</td></tr><tr><td>GED-4</td><td><strong>Archive recovery</strong> of a few files, then <strong>Classify</strong> each one.</td><td>Each scan goes into the right file; none is duplicated.</td></tr><tr><td>GED-5</td><td>Produce a certificate of enrolment from a <strong>template</strong>.</td><td>The PDF has the right name and class, on the school&#39;s letterhead, and is stored in the student&#39;s file.</td></tr></tbody></table><h2 id="site-and-general-management" tabindex="-1">Site and general management <a class="header-anchor" href="#site-and-general-management" aria-label="Permalink to &quot;Site and general management&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>To do</th><th>Expected</th></tr></thead><tbody><tr><td>DIR-1</td><td>Open <strong>To approve</strong>.</td><td>The leave request of TR-8 and the expense of CAI-3 (if under the threshold) are there.</td></tr><tr><td>DIR-2</td><td><strong>Grant</strong> the leave, <strong>Reject</strong> the expense with a reason.</td><td>Each requester gets the notification, with the reason when refused.</td></tr><tr><td>DIR-3</td><td>Open <strong>Pilotage</strong>.</td><td>The figures include the payments, absences and grades from the checklist.</td></tr><tr><td>DG-1</td><td>General management: open <strong>To approve</strong>.</td><td>It also shows expenses above the threshold and requests from every site.</td></tr><tr><td>DG-2</td><td>Have the cashier enter an expense above the threshold, then open <strong>To approve</strong> as site management.</td><td>The expense isn&#39;t there; it only appears for general management.</td></tr></tbody></table><h2 id="at-the-end" tabindex="-1">At the end <a class="header-anchor" href="#at-the-end" aria-label="Permalink to &quot;At the end&quot;">​</a></h2><ul><li>Cancel or delete the &quot;Acceptance test&quot; data created during the checklist, including a refund of the PAR-5 online payment if needed.</li><li>Send the list of failed items, with their numbers, before announcing the update.</li></ul>',32)])])}const u=e(d,[["render",o]]);export{p as __pageData,u as default};
